const crypto = require('crypto');

const uid = () => crypto.randomBytes(6).toString('hex').toUpperCase();
const txnId = 'TXN-' + uid();
const confCode = 'SIM-' + uid().slice(0,6);
const now = new Date().toISOString().replace('T',' ').slice(0,19);

const base = 124.00, taxes = 18.60, surcharge = 5.40, baggage = 50.00;
const total = base + taxes + surcharge + baggage;

console.log('='.repeat(60));
console.log('  ✈️  MOCK FLIGHT BOOKING SIMULATION');
console.log('  ⚠️  FOR DEMONSTRATION PURPOSES ONLY');
console.log('='.repeat(60));

console.log('\n📋 STEP 1 — Flight Details');
console.log('-'.repeat(60));
console.log('  Flight:      FLD3D594');
console.log('  Date:        2026-09-10');
console.log('  Route:       LAX (Los Angeles)');
console.log('            →  SFO (San Francisco)');
console.log('  Departure:   08:30');
console.log('  Arrival:     10:00');
console.log('  Duration:    1h 30m');
console.log('  Class:       Economy');
console.log('  Type:        Direct (non-stop)');
console.log('  Aircraft:    Boeing 737-800');

console.log('\n💰 STEP 2 — Pricing Breakdown');
console.log('-'.repeat(60));
console.log('  Base fare (Economy):       \$' + base.toFixed(2).padStart(9));
console.log('  Taxes & fees:              \$' + taxes.toFixed(2).padStart(9));
console.log('  Carrier surcharge:         \$' + surcharge.toFixed(2).padStart(9));
console.log('  Extra baggage (1 bag):     \$' + baggage.toFixed(2).padStart(9));
console.log('                             ' + '─'.repeat(11));
console.log('  TOTAL:                     \$' + total.toFixed(2).padStart(9));

console.log('\n💳 STEP 3 — Payment (SIMULATED)');
console.log('-'.repeat(60));
console.log('  Payment method:     Mastercard');
console.log('  Card:               ••••-••••-••••-7890');
console.log('  Cardholder:         VALUED CUSTOMER');
console.log('  Amount charged:     \$' + total.toFixed(2) + ' USD');
console.log('  Transaction ID:     ' + txnId);
console.log('  Status:             APPROVED ✅');

console.log('\n🎫 STEP 4 — Booking Confirmation');
console.log('-'.repeat(60));
console.log('  Confirmation code:  ' + confCode);
console.log('  Booked at:          ' + now);
console.log('  Passenger:          VALUED CUSTOMER');
console.log('  Seat:               14A (Window)');
console.log('  Boarding group:     C');

console.log();
console.log('='.repeat(60));
console.log('  ✅  MOCK BOOKING CONFIRMED');
console.log();
console.log('  FLD3D594  |  2026-09-10  |  LAX → SFO');
console.log('  Economy   |  \$' + total.toFixed(2) + ' USD  |  ' + confCode);
console.log();
console.log('  ⚠️  THIS IS A SIMULATION — NO REAL BOOKING WAS MADE');
console.log('  ⚠️  NO PAYMENT WAS PROCESSED');
console.log('='.repeat(60));
